{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California tenant screening fee cap and rights","requirement":"A landlord may not charge a tenant screening fee above the statutory maximum ($68.96 for 2026), must use a reusable screening report if the tenant provides one, and must give the applicant a receipt, a copy of any consumer credit report obtained, and a refund of any unused portion.","key_value":"$68.96 maximum for 2026","coverage_conditions":"Applies to residential rental applicants in California; no fee may be charged if no rental unit is actually available.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental applicants"},"exemptions":null,"penalty":null,"effective_date":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is $68.96","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley screening fee rights disclosure and non-refundable fee ban","requirement":"Before collecting a screening fee, an owner must give the applicant a tenant screening fee rights statement and the state maximum fee cap; an owner may not charge an existing tenant a non-refundable fee to renew a tenancy or to change roommates.","key_value":null,"coverage_conditions":"Applies to all residential rental agreements in Berkeley, regardless of contrary lease language.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All residential rental agreements"},"exemptions":null,"penalty":"Any lease provision that violates the chapter is unenforceable.","effective_date":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"confidence":0.85,"conflict_flag":false,"conflict_note":null}
